ROOT=pathlib.Path(__file__).resolve().parents[3];OUT=pathlib.Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--label',required=True);a=ap.parse_args();out=OUT/a.label
 if out.exists():raise ValueError('Choose an immutable new result label')
 out.mkdir();expected={'tools/quality.py':'03f24f7e9b89979e30facf258f8c8f9f358b1aca2de876a1adae5e058f0fc96b','tools/workflow.py':'11dc7a916d00a3b67528b63f7d6b02a74e9b895972f7ce56ec540d245b54872b','tools/review_preflight.py':'de09542da3c32f73f6f89a84709e63616fc8516f2ba6cbec08599443b5c878c5'};before={p:sha(ROOT/p) for p in expected};assert before==expected
 prefix='reviews/week01/independent-transfer-20261111/';q=prefix+'quality.json';wf=prefix+'workflow.json';calls=[('evaluate',['tools/quality.py','evaluate',q,'--root','.']),('plan',['tools/quality.py','plan',q,'--root','.']),('workflow-validate',['tools/workflow.py','validate',wf,'--root','.']),('workflow-decide',['tools/workflow.py','decide',wf,'--quality',q,'--root','.']),('preflight',['tools/review_preflight.py','--root','.','--depth',prefix+'depth.json','--graph',prefix+'graph.json','--paths',prefix+'paths.json','--semantic-review',prefix+'semantic-review.json','--state',wf,'--quality',q]),('review-context-unit',['tools/quality.py','review-context',q,'--criterion','K05','--object','W1-table','--root','.']),('review-context-claim',['tools/quality.py','review-context',q,'--criterion','K06','--object','claim:table','--root','.']),('impact-unlinked-PLAN',['tools/quality.py','impact',q,'--changed','PLAN','--root','.'])];values={};receipts=[]
 for name,args in calls:
  argv=[sys.executable,'-B',*args];p=subprocess.run(argv,cwd=ROOT,text=True,capture_output=True);v=json.loads(p.stdout);values[name]=v;(out/(name+'.json')).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n');receipts.append({'name':name,'argv':argv,'exit_code':p.returncode,'stdout_sha256':hashlib.sha256(p.stdout.encode()).hexdigest(),'stderr':p.stderr});assert p.returncode==(1 if name=='preflight' else 0),(name,p.returncode,p.stderr)
 sr=values['evaluate']['selective_review'];checks={'evaluate_matches_K12':sr==next(c['measurement'] for c in values['evaluate']['checks'] if c['id']=='K12'),'plan_forwards_exact_selective_review':values['plan']['selective_review']==sr,'workflow_forwards_exact_selective_review_while_paused':values['workflow-decide']['selective_review']==sr and values['workflow-decide']['status']=='pause' and values['workflow-decide']['reason']=='criteria_agreement_required','preflight_forwards_exact_selective_review_while_blocked':values['preflight']['selective_review']==sr and values['preflight']['status']=='blocked','preflight_nested_workflow_forwards_same':values['preflight']['workflow']['selective_review']==sr,'unit_context_capture_reports_missing_bindings_not_approval':values['review-context-unit']['plan_bindings']['required'] and bool(values['review-context-unit']['plan_bindings']['issues']) and bool(values['review-context-unit']['context_bindings']),'claim_capture_has_no_unit_plan_requirement':values['review-context-claim']['plan_bindings']['required'] is False,'legacy_unlinked_PLAN_impact_does_not_infer_edges':values['impact-unlinked-PLAN']['affected']==['PLAN'],'real_aggregate_remains_uncertain_not_ready':values['evaluate']['status']=='uncertain' and not values['evaluate']['ready_for_review'],'source_read_snapshots_present':any(c['kind']=='source_read' for c in values['review-context-claim']['context_bindings'])}
 baseline=json.loads((OUT/'baseline-01/results.json').read_text());originals={p:sha(ROOT/p) for p in baseline['original_protected_paths_before']};index=pathlib.Path(subprocess.check_output(['git','rev-parse','--git-path','index'],cwd=ROOT,text=True).strip());index=index if index.is_absolute() else ROOT/index;after={p:sha(ROOT/p) for p in expected};result={'recorded_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_code_expected':expected,'source_code_before':before,'source_code_after':after,'source_code_stable_during_commands':before==after,'calls':receipts,'checks':checks,'original_lesson_record_workflow_hashes_match_baseline':originals==baseline['original_protected_paths_before'],'current_original_hashes':originals,'git_index_sha256':sha(index),'git_index_matches_initial_reproduction':sha(index)==baseline['git_index_before'],'actual_current_state':{'quality':values['evaluate']['status'],'quality_ready':values['evaluate']['ready_for_review'],'plan':{k:values['plan'][k] for k in ['status','reason']},'workflow':{k:values['workflow-decide'][k] for k in ['status','reason']},'preflight':values['preflight']['status'],'preflight_blockers':[x['code'] for x in values['preflight']['blockers']],'stored_reviews_not_modified':True},'limits':['CLI captures are read-only; propagation exposes tasks and does not perform a content review or create acceptance.','The actual real record remains unbound at unit plan scope and uncertain overall. Copied mechanical probes are separately labeled and are not supplied as new reviews here.']};(out/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');ok=all(checks.values()) and before==after and originals==baseline['original_protected_paths_before'];print(json.dumps({'label':a.label,'all_checks_passed':ok,'checks':checks,'actual_current_state':result['actual_current_state']},ensure_ascii=False));return 0 if ok else 2
